/* המירוץ ל-100 — page logic. Data comes from data.js (window.RACE_DATA), generated by scripts/build-data.js. */
(function () {
  'use strict';

  var DATA = window.RACE_DATA || { partA: [], partB: [], auditions: [], pairs: [], hero: null };
  var LOGO = 'assets/logo.webp';
  var TABS = ['part-a', 'part-b', 'pairs', 'auditions'];

  // ---------- Normalize data into card items ----------
  function videoItem(v) {
    // YouTube link wins over Drive when both exist.
    var yt = v.youtubeId || null;
    return {
      kind: yt ? 'youtube' : 'drive',
      race: true,
      id: yt || v.driveId || null,
      num: v.num,
      title: v.title,
      meta: v.meta || '',
      desc: v.desc || '',
      duration: v.duration || '',
      thumb: v.thumb || (yt ? 'https://img.youtube.com/vi/' + encodeURIComponent(yt) + '/hqdefault.jpg' : null),
    };
  }
  function pairItem(p) {
    return {
      kind: 'youtube',
      id: p.youtubeId || null,
      num: p.num,
      title: p.team,
      meta: (p.members || []).join(' · '),
      desc: '',
      duration: '',
      thumb: p.youtubeId ? 'https://img.youtube.com/vi/' + encodeURIComponent(p.youtubeId) + '/hqdefault.jpg' : null,
    };
  }

  var lists = {
    partA: (DATA.partA || []).map(videoItem),
    partB: (DATA.partB || []).map(videoItem),
    auditions: (DATA.auditions || []).map(videoItem),
    pairs: (DATA.pairs || []).map(pairItem),
  };
  // Playlists for prev/next inside the player (only playable items).
  var playlists = {
    race: lists.partA.concat(lists.partB).filter(function (i) { return i.id; }),
    auditions: lists.auditions.filter(function (i) { return i.id; }),
    pairs: lists.pairs.filter(function (i) { return i.id; }),
  };
  var playlistOf = { partA: 'race', partB: 'race', auditions: 'auditions', pairs: 'pairs' };

  // ---------- Helpers ----------
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }
  function placeholder(num) {
    var ph = el('span', 'placeholder');
    var img = el('img');
    img.src = LOGO;
    img.alt = '';
    ph.appendChild(img);
    if (num) ph.appendChild(el('span', 'ph-num', String(num)));
    return ph;
  }

  // ---------- Cards ----------
  function renderCard(item, listName) {
    var li = el('li');
    var playable = !!item.id;
    var card = el(playable ? 'button' : 'div', 'card' + (playable ? '' : ' is-soon'));
    if (playable) {
      card.type = 'button';
      card.setAttribute('aria-label', (item.meta ? item.meta + ', ' : '') + item.title + (item.duration ? ', ' + item.duration : ''));
      card.addEventListener('click', function () {
        var pl = playlists[playlistOf[listName]];
        openPlayer(pl, pl.indexOf(item), card);
      });
    }

    var thumb = el('span', 'thumb');
    if (item.thumb) {
      var img = el('img', 'cover');
      img.src = item.thumb;
      img.alt = '';
      img.loading = 'lazy';
      img.decoding = 'async';
      img.addEventListener('error', function () { img.replaceWith(placeholder(item.race ? item.num : null)); });
      thumb.appendChild(img);
    } else {
      thumb.appendChild(placeholder(item.race ? item.num : null));
    }
    if (item.duration && playable) {
      var b = el('span', 'badge', item.duration);
      b.setAttribute('aria-hidden', 'true');
      thumb.appendChild(b);
    }
    if (!playable) thumb.appendChild(el('span', 'badge-soon', 'בקרוב'));
    card.appendChild(thumb);

    if (item.meta) card.appendChild(el('p', 'card-meta', item.meta));
    card.appendChild(el('h3', 'card-title', item.title));
    if (!playable) card.appendChild(el('span', 'sr-only', '(הסרטון יעלה בקרוב)'));

    li.appendChild(card);
    return li;
  }

  function renderLists() {
    document.querySelectorAll('[data-list]').forEach(function (ul) {
      var name = ul.getAttribute('data-list');
      var items = lists[name] || [];
      ul.textContent = '';
      if (!items.length) {
        var empty = el('li', 'empty-state');
        var img = el('img');
        img.src = LOGO;
        img.alt = '';
        empty.appendChild(img);
        empty.appendChild(el('span', null, 'הסרטונים יעלו בקרוב'));
        ul.appendChild(empty);
        return;
      }
      items.forEach(function (item) { ul.appendChild(renderCard(item, name)); });
    });
  }

  // ---------- Hero ----------
  function setupHero() {
    var bg = document.getElementById('hero-bg');
    // Hero photo only when assets/hero.jpg exists; otherwise a compact gradient hero.
    var src = DATA.hero;
    if (src) {
      bg.style.backgroundImage = 'url("' + encodeURI(src) + '")';
    } else {
      bg.classList.add('is-fallback');
      bg.parentNode.classList.add('hero--compact');
    }

    var cta = document.getElementById('cta-start');
    var note = document.getElementById('cta-note');
    var race = playlists.race;
    if (!race.length) {
      cta.setAttribute('aria-disabled', 'true');
      cta.setAttribute('aria-describedby', 'cta-note');
      note.hidden = false;
    }
    cta.addEventListener('click', function () {
      if (!race.length) return;
      openPlayer(race, 0, cta); // first playable video in race order (video 1 once it has a link)
    });
  }

  // ---------- Tabs (synced to URL hash) ----------
  var tabButtons = Array.prototype.slice.call(document.querySelectorAll('[role="tab"]'));

  function selectTab(name, opts) {
    opts = opts || {};
    if (TABS.indexOf(name) < 0) name = TABS[0];
    tabButtons.forEach(function (btn) {
      var on = btn.getAttribute('data-tab') === name;
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
      btn.tabIndex = on ? 0 : -1;
      document.getElementById(btn.getAttribute('aria-controls')).hidden = !on;
      if (on && opts.focus) btn.focus();
    });
    document.querySelectorAll('[data-tab-link]').forEach(function (a) {
      a.setAttribute('aria-current', a.getAttribute('data-tab-link') === name ? 'true' : 'false');
    });
    if (opts.updateHash && location.hash !== '#' + name) {
      history.replaceState(null, '', '#' + name);
    }
  }

  function tabFromHash() {
    var h = decodeURIComponent((location.hash || '').slice(1));
    return TABS.indexOf(h) >= 0 ? h : null;
  }

  function setupTabs() {
    tabButtons.forEach(function (btn, i) {
      btn.addEventListener('click', function () {
        selectTab(btn.getAttribute('data-tab'), { updateHash: true });
      });
      btn.addEventListener('keydown', function (e) {
        // RTL: ArrowLeft moves forward (to the next tab on the left), ArrowRight moves back.
        var idx = null;
        if (e.key === 'ArrowLeft') idx = (i + 1) % tabButtons.length;
        else if (e.key === 'ArrowRight') idx = (i - 1 + tabButtons.length) % tabButtons.length;
        else if (e.key === 'Home') idx = 0;
        else if (e.key === 'End') idx = tabButtons.length - 1;
        if (idx === null) return;
        e.preventDefault();
        selectTab(tabButtons[idx].getAttribute('data-tab'), { focus: true, updateHash: true });
      });
    });

    window.addEventListener('hashchange', function () {
      var t = tabFromHash();
      if (!t) return;
      selectTab(t);
      document.getElementById('main').scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
    // Header links: also scroll when the hash is already the same tab
    document.querySelectorAll('[data-tab-link]').forEach(function (a) {
      a.addEventListener('click', function () {
        if (location.hash === a.getAttribute('href')) {
          document.getElementById('main').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      });
    });

    selectTab(tabFromHash() || TABS[0]);
  }

  // ---------- Player modal ----------
  var modal = document.getElementById('player');
  var frame = document.getElementById('player-frame');
  var mTitle = document.getElementById('player-title');
  var mMeta = document.getElementById('player-meta');
  var mDesc = document.getElementById('player-desc');
  var mPos = document.getElementById('player-pos');
  var btnPrev = document.getElementById('player-prev');
  var btnNext = document.getElementById('player-next');
  var btnClose = document.getElementById('player-close');
  var btnFs = document.getElementById('player-fs');
  var current = { list: [], index: -1, opener: null };

  function embedUrl(item) {
    var id = encodeURIComponent(item.id);
    if (item.kind === 'youtube') return 'https://www.youtube-nocookie.com/embed/' + id + '?autoplay=1&rel=0';
    return 'https://drive.google.com/file/d/' + id + '/preview';
  }

  function show(index) {
    var item = current.list[index];
    if (!item) return;
    current.index = index;
    var metaParts = [];
    if (item.meta) metaParts.push(item.meta);
    if (item.duration) metaParts.push(item.duration);
    mMeta.textContent = metaParts.join(' · ');
    mMeta.hidden = !metaParts.length;
    mTitle.textContent = item.title;
    mDesc.textContent = item.desc;
    mDesc.hidden = !item.desc;
    frame.title = 'נגן וידאו: ' + item.title;
    frame.src = embedUrl(item);
    frame.parentNode.classList.toggle('is-drive', item.kind === 'drive');
    btnPrev.disabled = index <= 0;
    btnNext.disabled = index >= current.list.length - 1;
    mPos.textContent = (index + 1) + ' / ' + current.list.length;
  }

  function openPlayer(list, index, opener) {
    if (!list || index < 0 || !list[index]) return;
    current.list = list;
    current.opener = opener || document.activeElement;
    modal.hidden = false;
    document.body.classList.add('modal-open');
    show(index);
    btnClose.focus();
  }

  function closePlayer() {
    if (modal.hidden) return;
    frame.src = 'about:blank'; // stop playback
    frame.removeAttribute('src');
    modal.hidden = true;
    document.body.classList.remove('modal-open');
    if (current.opener && document.contains(current.opener)) current.opener.focus();
  }

  function go(delta) {
    var i = current.index + delta;
    if (i < 0 || i >= current.list.length) return;
    show(i);
  }

  function focusables() {
    return Array.prototype.slice.call(
      modal.querySelectorAll('button:not(:disabled), a[href], iframe')
    ).filter(function (n) { return !n.hidden && n.offsetParent !== null; });
  }

  function setupPlayer() {
    modal.querySelectorAll('[data-close]').forEach(function (n) { n.addEventListener('click', closePlayer); });
    btnPrev.addEventListener('click', function () { go(-1); });
    // Hide the full-screen button where the browser can't do it (e.g. iPhone Safari).
    if (!(document.fullscreenEnabled || document.webkitFullscreenEnabled)) btnFs.hidden = true;
    btnNext.addEventListener('click', function () { go(1); });
    btnFs.addEventListener('click', function () {
      // Full screen on the player (and landscape where the phone allows it).
      var fn = frame.requestFullscreen || frame.webkitRequestFullscreen;
      if (!fn) return;
      var lock = function () {
        try { if (screen.orientation && screen.orientation.lock) screen.orientation.lock('landscape').catch(function () {}); } catch (e) {}
      };
      try {
        var r = fn.call(frame);
        if (r && r.then) r.then(lock, function () {}); else lock();
      } catch (e) {}
    });

    document.addEventListener('keydown', function (e) {
      if (modal.hidden) return;
      if (e.key === 'Escape') { e.preventDefault(); closePlayer(); return; }
      // RTL: ← (left) = next, → (right) = previous
      if (e.key === 'ArrowLeft') { e.preventDefault(); go(1); return; }
      if (e.key === 'ArrowRight') { e.preventDefault(); go(-1); return; }
      if (e.key === 'Tab') {
        var f = focusables();
        if (!f.length) return;
        var first = f[0], last = f[f.length - 1];
        if (e.shiftKey && (document.activeElement === first || !modal.contains(document.activeElement))) {
          e.preventDefault(); last.focus();
        } else if (!e.shiftKey && (document.activeElement === last || !modal.contains(document.activeElement))) {
          e.preventDefault(); first.focus();
        }
      }
    });
    // If focus escapes the dialog (e.g. via a click), pull it back.
    document.addEventListener('focusin', function (e) {
      if (!modal.hidden && !modal.contains(e.target)) btnClose.focus();
    });
  }

  // ---------- Init ----------
  renderLists();
  setupHero();
  setupTabs();
  setupPlayer();
})();
